px;text-align:right">{{employer_esi}}</td><td style="border:1px solid #222;padding:7px"></td><td style="border:1px solid #222;padding:7px"></td><td style="border:1px solid #222;padding:7px"></td></tr><tr><td style="border:1px solid #222;padding:7px;text-align:right"><b>TOTAL</b></td><td style="border:1px solid #222;padding:7px;text-align:right"><b>{{gross}}</b></td><td style="border:1px solid #222;padding:7px;text-align:right"><b>{{gross}}</b></td><td style="border:1px solid #222;padding:7px"></td><td style="border:1px solid #222;padding:7px"></td></tr><tr><td colspan="4" style="border:1px solid #222;padding:8px;font-size:17px"><b>NET PAY</b></td><td style="border:1px solid #222;padding:8px;text-align:right;font-size:17px"><b>{{net_pay}}</b></td></tr><tr><td colspan="5" style="border:1px solid #222;padding:8px"><b>In Words:</b> {{net_pay_words}}</td></tr></table><p style="font-size:12px;margin-top:18px">{{payslip_footer}}</p></div>
HTML;
