$template = (string)($settings['payslip_template'] ?? '') ?: $defaultTemplate;
$tokens = ['{{company_logo}}','{{company_name}}','{{company_address}}','{{company_email}}','{{company_phone}}','{{employee_name}}','{{employee_code}}','{{device_employee_id}}','{{designation}}','{{department}}','{{join_date}}','{{bank_name}}','{{bank_account}}','{{pan}}','{{uan}}','{{esi_no}}','{{aadhar}}','{{location}}','{{mode_of_pay}}','{{payroll_month}}','{{days_pay}}','{{paid_days}}','{{basic}}','{{hra}}','{{allowance}}','{{gross}}','{{pf}}','{{esi}}','{{professional_tax}}','{{employer_pf}}','{{employer_esi}}','{{deductions}}','{{net_pay}}','{{net_pay_words}}','{{leave_details}}','{{payslip_footer}}'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
	$footer = trim((string)($_POST['payslip_footer'] ?? ''));
	$policy = trim((string)($_POST['leave_policy'] ?? ''));
	$template = trim((string)($_POST['payslip_template'] ?? $template));
	if (($_POST['template_action'] ?? '') === 'reference') {
		$template = $referenceTemplate;
	}
	$st = $hrDb->prepare('INSERT INTO hr_settings(company_id,payslip_footer,leave_policy,payslip_template) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE payslip_footer=VALUES(payslip_footer),leave_policy=VALUES(leave_policy),payslip_template=VALUES(payslip_template)');
	$st->bind_param('isss', $companyId, $footer, $policy, $template);
	$st->execute();
	$st->close();
	hrFlash('Payslip design saved.');
	header('Location: formats.php');
	exit;
}
hrPageStart('Brand & formats');
