<script>
const editor = document.querySelector('#payslipEditor');
const sampleValues = { '{{company_logo}}':'<div style="font-size:11px;color:#64748b">[Company logo]</div>', '{{company_name}}':'Acme Technologies Pvt Ltd', '{{company_address}}':'Kolkata, West Bengal', '{{company_email}}':'hr@acme.test', '{{company_phone}}':'+91 33 4000 1000', '{{employee_name}}':'Sarah Mitchell', '{{employee_code}}':'EMP-001', '{{device_employee_id}}':'1001', '{{designation}}':'Product Designer', '{{department}}':'Product Design', '{{join_date}}':'01 Jan 2025', '{{bank_name}}':'HDFC Bank', '{{bank_account}}':'•••• 4582', '{{pan}}':'ABCDE1234F', '{{payroll_month}}':'September 2026', '{{paid_days}}':'26', '{{basic}}':'Rs. 72,000.00', '{{hra}}':'Rs. 18,000.00', '{{allowance}}':'Rs. 8,000.00', '{{gross}}':'Rs. 98,000.00', '{{pf}}':'Rs. 8,640.00', '{{esi}}':'Rs. 735.00', '{{professional_tax}}':'Rs. 200.00', '{{deductions}}':'Rs. 9,575.00', '{{net_pay}}':'Rs. 88,425.00', '{{leave_details}}':'Earned leave: 1 | Sick leave: 0 | Unpaid leave: 0', '{{payslip_footer}}':'This is a computer-generated payslip.' };
Object.assign(sampleValues, {'{{uan}}':'100198768954','{{esi_no}}':'Not registered','{{aadhar}}':'922713332075','{{location}}':'East Delhi','{{mode_of_pay}}':'Bank Transfer','{{days_pay}}':'31','{{employer_pf}}':'Rs. 1,800.00','{{employer_esi}}':'Rs. 0.00','{{net_pay_words}}':'Rupees Fifty Six Thousand Four Hundred Only'});
function updatePreview() { let html = editor.innerHTML; Object.entries(sampleValues).forEach(([key, value]) => { html = html.split(key).join(value); }); document.querySelector('#payslipLivePreview').innerHTML = html; }
document.querySelectorAll('[data-command]').forEach(button => button.addEventListener('click', () => { editor.focus(); document.execCommand(button.dataset.command, false, button.dataset.value || null); }));
document.querySelector('#designerColor').addEventListener('input', event => { editor.focus(); document.execCommand('foreColor', false, event.target.value); });
document.querySelectorAll('[data-token]').forEach(button => button.addEventListener('click', () => { editor.focus(); document.execCommand('insertText', false, button.dataset.token); }));
editor.addEventListener('input', updatePreview); updatePreview();
document.querySelector('#payslipDesignerForm').addEventListener('submit', () => { document.querySelector('#payslipTemplate').value = editor.innerHTML; });
</script>
